import{_ as e,o as a,c as n,a2 as l}from"./chunks/framework.CHX4lV2z.js";const h=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"platform-concepts/plugins.md","filePath":"platform-concepts/plugins.md","lastUpdated":1789811186000}'),s={name:"platform-concepts/plugins.md"};function i(r,t,o,d,p,u){return a(),n("div",null,[...t[0]||(t[0]=[l('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>The current LightRSI architecture separates reusable feature packages, presets, host adapters, and user-facing products. The word <strong>plugin</strong> also appears in host installation commands, where it refers to a host&#39;s native integration mechanism.</p><h2 id="plugin-model" tabindex="-1">Packages, Presets, and Products <a class="header-anchor" href="#plugin-model" aria-label="Permalink to &quot;Packages, Presets, and Products {#plugin-model}&quot;">​</a></h2><p>These layers have different responsibilities:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Shared packages</strong></td><td style="text-align:left;">Foundation infrastructure and composable features such as stabilization, reduction, and eviction</td></tr><tr><td style="text-align:left;"><strong>Presets</strong></td><td style="text-align:left;">Verified feature combinations, including TokenPilot</td></tr><tr><td style="text-align:left;"><strong>Host adapters</strong></td><td style="text-align:left;">Host discovery, installation, runtime hooks, and product registration</td></tr><tr><td style="text-align:left;"><strong>Products</strong></td><td style="text-align:left;">User-facing workflows and surfaces, including Context Cleaner, the shared CLI, and MCP interfaces</td></tr></tbody></table><h2 id="current-plugins" tabindex="-1">TokenPilot and Context Cleaner <a class="header-anchor" href="#current-plugins" aria-label="Permalink to &quot;TokenPilot and Context Cleaner {#current-plugins}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/LightRSI/plugin-catalog/tokenpilot/overview">TokenPilot</a></td><td style="text-align:left;">Preset</td><td style="text-align:left;">Composes cache-aware context-management policies</td></tr><tr><td style="text-align:left;"><a href="/LightRSI/user-guide/context-cleaner">Context Cleaner</a></td><td style="text-align:left;">Product</td><td style="text-align:left;">Presents tasks and recommendations, takes explicit approval, and reports cleanup status</td></tr></tbody></table><p>Cleaner reuses shared task lifecycle and host rewrite capabilities. Its public workflow is available for OpenClaw, Codex, and Claude Code; DeepSeek Harness does not currently expose a public Cleaner entrypoint.</p><h2 id="native-host-plugins" tabindex="-1">Native Host Plugins <a class="header-anchor" href="#native-host-plugins" aria-label="Permalink to &quot;Native Host Plugins&quot;">​</a></h2><p>TokenPilot integrates with OpenClaw, Codex, Claude Code, and <a href="/LightRSI/hosts/deepseek-harness">DeepSeek Harness</a>. OpenClaw uses a native plugin slot; Harness uses a native Cordis plugin for optional context eviction and session status. Codex uses a local proxy and hooks, while Claude Code uses a local gateway and MCP.</p><p>These integration mechanisms do not make every product or feature available on every host. See <a href="/LightRSI/hosts/compatibility">Host Compatibility</a> for the supported combinations.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/LightRSI/platform-concepts/plugin-lifecycle">Plugin Lifecycle</a> — the state machine</li><li><a href="/LightRSI/plugin-catalog/tokenpilot/overview">TokenPilot Overview</a> — explore the preset</li><li><a href="/LightRSI/user-guide/context-cleaner">Context Cleaner</a> — use the cleanup product</li><li><a href="/LightRSI/plugin-development/build-your-first-plugin">Build Your First Plugin</a> — start developing</li></ul>',13)])])}const g=e(s,[["render",i]]);export{h as __pageData,g as default};
